function safe(name) {
  try { return $(name).first().json || {}; } catch (e) { return { _error: true, _message: String(e.message || e) }; }
}

const analysis = safe('Get Storage Analysis');
const prev = safe('Get Previous Snapshot');
const meta = safe('Get Advisor Meta');
const now = new Date().toISOString();

if (analysis._error || !analysis.checked_at) {
  return [{
    json: {
      should_emit: false,
      skip_persist: true,
      error: analysis._message || 'storage_analysis_unavailable',
    },
  }];
}

// Optional growth recompute if agent didn't get previous (agent call is without previous)
const GB = 1000 ** 3;
const prevCats = Array.isArray(prev.category_snapshot) ? prev.category_snapshot : [];
const prevMap = {};
for (const c of prevCats) {
  if (c && c.category) prevMap[c.category] = Number(c.bytes || 0);
}
const growth = [];
for (const c of (analysis.categories || [])) {
  const prevB = prevMap[c.category];
  if (prevB === undefined || prevB === null) continue;
  const curB = Number(c.bytes || 0);
  const delta = curB - prevB;
  if (delta >= 2 * GB || (prevB > 0 && curB >= 4 * prevB && delta >= 500 * 1000 * 1000)) {
    growth.push({ category: c.category, previous_bytes: prevB, current_bytes: curB, delta_bytes: delta });
  }
}

let recommendation = analysis.recommendation || 'no_action';
let overall = analysis.overall_status || 'healthy';
let severity = 'info';
let eventName = null;

if (growth.length) {
  recommendation = 'investigate_growth';
  if (overall === 'healthy') overall = 'attention';
  eventName = 'storage_growth_detected';
  severity = 'warning';
}

const low = Number(analysis.estimated_reclaimable_low_risk_bytes || 0);
const review = Number(analysis.estimated_reclaimable_review_bytes || 0);
const fingerprint = [
  recommendation,
  overall,
  String(low),
  String(review),
  String(analysis.disk_pressure || ''),
  growth.map((g) => g.category + ':' + g.delta_bytes).join(','),
].join('|');

const prevFp = meta.last_fingerprint || prev.fingerprint || null;
let should_emit = false;
if (!prevFp) {
  // first run: emit only if actionable
  if (recommendation !== 'no_action' || low >= GB || review >= GB || growth.length) {
    should_emit = true;
    eventName = eventName || (growth.length ? 'storage_growth_detected' : 'cleanup_opportunity_detected');
  }
} else if (prevFp !== fingerprint) {
  should_emit = true;
  if (!eventName) {
    if (meta.last_recommendation && meta.last_recommendation !== recommendation) {
      eventName = 'cleanup_recommendation_changed';
      severity = 'warning';
    } else if (growth.length) {
      eventName = 'storage_growth_detected';
      severity = 'warning';
    } else {
      eventName = 'cleanup_opportunity_detected';
      severity = recommendation === 'no_action' ? 'info' : 'info';
    }
  }
}

// sanitize categories for persistence/events — no paths beyond category names
const category_snapshot = (analysis.categories || []).map((c) => ({
  category: c.category,
  bytes: c.bytes ?? null,
  candidate: !!c.candidate,
  risk: c.risk,
  confidence: c.confidence,
  recommendation: c.recommendation,
  protected: !!c.protected,
  status: c.status,
}));

const disk_snapshot = analysis.disk_snapshot || {};

return [{
  json: {
    should_emit,
    skip_persist: false,
    checked_at: analysis.checked_at || now,
    disk_snapshot,
    category_snapshot,
    estimated_low_risk_bytes: low,
    estimated_review_bytes: review,
    protected_bytes: Number(analysis.protected_bytes || 0),
    overall_status: overall,
    recommendation,
    fingerprint,
    details: {
      disk_pressure: analysis.disk_pressure,
      worst_used_percent: analysis.worst_used_percent,
      growth,
      partial: !!analysis.partial,
      execution_ms: analysis.execution_ms,
      advisory_only: true,
      executed_cleanup: false,
    },
    event: should_emit ? {
      source: 'storage_cleanup_advisor',
      severity,
      component: 'storage',
      event: eventName || 'cleanup_opportunity_detected',
      status: overall,
      timestamp: now,
      message: `Análise de armazenamento: ${recommendation}. low_risk≈${(low/GB).toFixed(1)}GB review≈${(review/GB).toFixed(1)}GB. Nenhuma remoção foi realizada.`,
      details: {
        estimated_low_risk_bytes: low,
        estimated_review_bytes: review,
        protected_bytes: Number(analysis.protected_bytes || 0),
        recommendation,
        overall_status: overall,
        disk_pressure: analysis.disk_pressure,
        worst_used_percent: analysis.worst_used_percent,
        growth,
        categories: category_snapshot.filter((c) => c.candidate || c.protected).map((c) => ({
          category: c.category, bytes: c.bytes, risk: c.risk, candidate: c.candidate, protected: c.protected,
        })),
        advisory_only: true,
        executed_cleanup: false,
      },
      requires_attention: severity !== 'info',
      suggested_action: recommendation === 'no_action' ? null : 'Revisar recomendações; não executar cleanup automático.',
      correlation_id: `storage-cleanup:${eventName || 'opportunity'}`,
    } : null,
    meta_update: {
      last_fingerprint: fingerprint,
      last_recommendation: recommendation,
      last_overall_status: overall,
    },
  },
}];

