(() => {
  if ($json.skip_persist) return 'SELECT 1 AS skipped;';
  const esc = (v) => String(v ?? '').replace(/'/g, "''");
  const disk = JSON.stringify($json.disk_snapshot || {}).replace(/'/g, "''");
  const cats = JSON.stringify($json.category_snapshot || []).replace(/'/g, "''");
  const details = JSON.stringify($json.details || {}).replace(/'/g, "''");
  const nul = (v) => (v === null || v === undefined) ? 'NULL' : String(Number(v));
  return `
INSERT INTO storage_cleanup_advisor_state (
  checked_at, disk_snapshot, category_snapshot,
  estimated_low_risk_bytes, estimated_review_bytes, protected_bytes,
  overall_status, recommendation, fingerprint, details
) VALUES (
  '${esc($json.checked_at)}'::timestamptz,
  '${disk}'::jsonb,
  '${cats}'::jsonb,
  ${nul($json.estimated_low_risk_bytes)},
  ${nul($json.estimated_review_bytes)},
  ${nul($json.protected_bytes)},
  '${esc($json.overall_status)}',
  '${esc($json.recommendation)}',
  '${esc($json.fingerprint)}',
  '${details}'::jsonb
);`;
})()
}}

